import Database from 'better-sqlite3';
import path from 'path';

const dbPath = path.resolve('data/blog.db');
console.log('Connecting to database at:', dbPath);
const db = new Database(dbPath);

// Check if posts table exists
const tableCheck = db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='posts'").get();
if (tableCheck) {
  console.log('Success: "posts" table exists.');
} else {
  console.log('Error: "posts" table does not exist.');
  process.exit(1);
}

// Insert test data
const insert = db.prepare(`
  INSERT INTO posts (slug, title, content, published, created_at)
  VALUES (?, ?, ?, ?, ?)
`);

try {
  insert.run('hello-world', 'Hello World', 'This is my first published post.', 1, new Date().toISOString());
  insert.run('draft-post', 'Draft Post', 'This is a draft.', 0, new Date().toISOString());
  console.log('Success: Test posts inserted.');
} catch (err) {
  console.log('Note/Error inserting test data:', err.message);
}

// Query posts
const posts = db.prepare('SELECT * FROM posts').all();
console.log('All posts in DB:', posts);
db.close();
